import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';

test('overdueInvoices returns empty array when no invoices match criteria', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-12-25',
      status: 'paid',
      lines: [],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices filters by status: ignores draft invoices', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-01-10',
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 0);
});

test('overdueInvoices filters by status: ignores paid invoices', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-01-10',
      status: 'paid',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 0);
});

test('overdueInvoices includes issued invoices', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-01-10',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-001');
});

test('overdueInvoices includes partially_paid invoices', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-01-10',
      status: 'partially_paid',
      lines: [{ qty: 1, unitPrice: 100 }],
      payments: [{ amount: 50, date: '2024-02-01' }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-001');
});

test('overdueInvoices filters by date: excludes future due dates', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-12-25',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 0);
});

test('overdueInvoices filters by date: includes due dates before asOf', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-12-19',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 1);
});

test('overdueInvoices filters by date: excludes due dates equal to asOf', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-12-20',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 0);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-12-10',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result[0].daysOverdue, 10);
});

test('overdueInvoices calculates daysOverdue as 0 for one day overdue', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-12-19',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices returns correct due amount for issued invoice with no payments', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-01-10',
      status: 'issued',
      lines: [
        {
          qty: 1,
          unitPrice: 10000,
          discountPercent: 0,
          vatRate: 20,
        },
      ],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 1);
  // 10000 + (10000 * 0.20) = 12000
  assert.equal(result[0].due, 12000);
});

test('overdueInvoices returns correct due amount for partially_paid invoice', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-01-10',
      status: 'partially_paid',
      lines: [
        {
          qty: 1,
          unitPrice: 10000,
          discountPercent: 0,
          vatRate: 20,
        },
      ],
      payments: [{ amount: 5000, date: '2024-02-01' }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 1);
  // 12000 - 5000 = 7000
  assert.equal(result[0].due, 7000);
});

test('overdueInvoices sorts by daysOverdue descending (most overdue first)', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-12-10',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
    {
      number: 'INV-002',
      customerId: 'C-002',
      dueDate: '2024-12-15',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
    {
      number: 'INV-003',
      customerId: 'C-003',
      dueDate: '2024-12-05',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 3);
  assert.equal(result[0].number, 'INV-003');
  assert.equal(result[0].daysOverdue, 15);
  assert.equal(result[1].number, 'INV-001');
  assert.equal(result[1].daysOverdue, 10);
  assert.equal(result[2].number, 'INV-002');
  assert.equal(result[2].daysOverdue, 5);
});

test('overdueInvoices preserves all required fields in result', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-01-10',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 1);
  const item = result[0];
  assert.equal(typeof item.number, 'string');
  assert.equal(typeof item.customerId, 'string');
  assert.equal(typeof item.dueDate, 'string');
  assert.equal(typeof item.daysOverdue, 'number');
  assert.equal(typeof item.due, 'number');
});

test('overdueInvoices handles empty invoice array', () => {
  const result = overdueInvoices([], '2024-12-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices handles multiple invoices with same customer', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-12-10',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
    {
      number: 'INV-002',
      customerId: 'C-001',
      dueDate: '2024-12-15',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const result = overdueInvoices(invoices, '2024-12-20');
  assert.equal(result.length, 2);
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[1].customerId, 'C-001');
});

test('overdueInvoices does not mutate input array', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      dueDate: '2024-01-10',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100 }],
    },
  ];

  const originalLength = invoices.length;
  overdueInvoices(invoices, '2024-12-20');

  assert.equal(invoices.length, originalLength);
});
